import type { DrizzleEnvSchema } from "@saflib/drizzle/env";
import type { EnvEnvSchema } from "@saflib/env/env";
import type { NodeEnvSchema } from "@saflib/node/env";

/**
 * Environment variables for the `@sderickson/recipes-service-common` package, including inherited variables via `extends`.
 * Generated by `@saflib/env`. To update, make changes to the adjacent `env.schema.json`, navigate to the package root, and run `npm exec saf-env generate`.
 */
export interface RecipesServiceCommonEnvSchema
  extends DrizzleEnvSchema, EnvEnvSchema, NodeEnvSchema {
  RECIPES_SERVICE_HTTP_HOST: string;
}

/**
 * `process.env` casted to the `RecipesServiceCommonEnvSchema` type.
 */
export const typedEnv = (globalThis.process
  ? process.env
  : {}) as unknown as RecipesServiceCommonEnvSchema;
